(()=>{"use strict";const runtime=window.AxhubAnnotation,source=window.GIFT_AXHUB_SOURCE;if(!runtime||!source)throw new Error("Axhub annotation runtime or source is missing.");const modalType={tabs:"tab",placement:"placement",play:"play",banner:"banner",announcement:"announcement-rule"};const viewer=runtime.createAnnotationViewer({source,options:{getCurrentPageId:()=>window.GIFT_CURRENT_PAGE||"tabs",showToolbar:true,showThemeToggle:true,showColorFilter:true,onDirectoryRoute:node=>{window.GIFT_SET_PAGE?.(node.route);viewer.refresh();}}});window.GIFT_AXHUB_VIEWER=viewer;void viewer.start().then(()=>{const attach=()=>{const state=window.__AXHUB_PROTO_DEV__;if(!state){setTimeout(attach,80);return}const apply=value=>{const page=["tabs","placement","play","banner","announcement"].includes(value.admin_page)?value.admin_page:"tabs";window.GIFT_SET_PAGE?.(page);if(value.review_state==="edit")window.GIFT_OPEN_MODAL?.(modalType[page]);viewer.refresh();};apply(state.getState());state.subscribe(()=>requestAnimationFrame(()=>apply(state.getState())));};attach();});})();
